-- V90.r Production Order Execution Foundation
CREATE TABLE IF NOT EXISTS production_material_issue (issue_id TEXT PRIMARY KEY, production_order_id TEXT NOT NULL, order_material_id TEXT, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, location_id TEXT NOT NULL, warehouse_id TEXT NOT NULL, material_master_id TEXT NOT NULL, lot_id TEXT NOT NULL, issued_qty NUMERIC NOT NULL, uom TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'POSTED', issued_by TEXT NOT NULL, issued_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, notes TEXT);
CREATE INDEX IF NOT EXISTS ix_prod_issue_order ON production_material_issue(production_order_id,material_master_id,lot_id);
CREATE TABLE IF NOT EXISTS production_batch (batch_id TEXT PRIMARY KEY, production_order_id TEXT NOT NULL, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, location_id TEXT NOT NULL, batch_no TEXT NOT NULL, product_master_id TEXT NOT NULL, planned_qty NUMERIC NOT NULL, uom TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', operator_user_id TEXT, machine_id TEXT, start_at TEXT, end_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, notes TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS ux_production_batch_no ON production_batch(organization_id,entity_id,batch_no);
